() => {
  const links = Array.from(document.querySelectorAll('a'))
    .map(a => ({text: (a.innerText || '').trim(), href: a.href}))
    .filter(a => /figma|clickup\.com\/t/i.test(a.href) || /figma/i.test(a.text));
  const unique = [];
  const seen = new Set();
  for (const l of links) {
    if (!seen.has(l.href)) {
      seen.add(l.href);
      unique.push(l);
    }
  }
  return unique;
}

