import {jwtDecode} from 'jwt-decode';

export interface LoginContactLike {
  key?: string | null;
  value?: string | null;
}

export const isEmailLoginSession = (
  session: {accessToken?: string} | null | undefined,
): boolean => {
  const accessToken = session?.accessToken;
  if (!accessToken) {
    return false;
  }
  try {
    const decoded = jwtDecode<{username?: string}>(accessToken);
    return typeof decoded.username === 'string' && decoded.username.includes('@');
  } catch {
    return false;
  }
};

export const getPrimaryLoginContactValue = (
  contacts?: LoginContactLike[] | null,
): string => {
  const withValue = (contacts ?? []).filter(
    (item) => typeof item.value === 'string' && item.value.trim() !== '',
  );
  const email = withValue.find((item) =>
    (item.key || '').toLowerCase().startsWith('email'),
  );
  const phone = withValue.find((item) =>
    (item.key || '').toLowerCase().startsWith('phone'),
  );
  return (email?.value || phone?.value || withValue[0]?.value || '').trim();
};

const maskEmail = (email: string): string => {
  const at = email.lastIndexOf('@');
  if (at <= 0 || at === email.length - 1) {
    return '***';
  }
  const local = email.slice(0, at);
  const domain = email.slice(at + 1);
  const visibleCount = local.length === 1 ? 1 : 2;
  return `${local.slice(0, visibleCount)}***@${domain}`;
};

const maskPhoneNumber = (phoneNumber: string): string => {
  return phoneNumber.replace(
    /(\+\d{2,3}-\d{2})(\d{2,4})(\d{2})/,
    (_match, prefix: string, middle: string, suffix: string) => {
      const maskedPart =
        middle.length === 4 ? '****' : middle.length === 3 ? '***' : '**';
      return `${prefix}${maskedPart}${suffix}`;
    },
  );
};

export const maskLoginIdentifier = (value: string): string => {
  if (!value) {
    return '';
  }
  if (value.includes('@')) {
    return maskEmail(value);
  }
  const maskedPhone = maskPhoneNumber(value);
  if (maskedPhone !== value) {
    return maskedPhone;
  }
  if (value.length <= 4) {
    return '****';
  }
  return `${value.slice(0, 2)}****${value.slice(-2)}`;
};

